	struct ucl_stack *st;
	bool has_error = false;

	LL_FOREACH(parser->stack, st)
	{
		if (st->chunk != parser->chunks) {
			break; /* Not our chunk, give up */
		}
		if (st->e.params.flags & UCL_STACK_HAS_OBRACE) {
			if (parser->err == NULL) {
				utstring_new(parser->err);
